[
 {
  "type": "eyebrow",
  "text": "counts — live stat queries"
 },
 {
  "type": "columns",
  "columns": [
   [
    {
     "type": "stat",
     "label": "tasks in the epic",
     "query": {
      "filter": {
       "parent_id": "<epic-id>"
      }
     }
    }
   ],
   [
    {
     "type": "stat",
     "label": "still open",
     "query": {
      "filter": {
       "parent_id": "<epic-id>",
       "status": "open"
      }
     }
    }
   ],
   [
    {
     "type": "stat",
     "label": "done",
     "query": {
      "filter": {
       "parent_id": "<epic-id>",
       "status": "done"
      }
     }
    }
   ]
  ]
 },
 {
  "type": "chart",
  "kind": "bars",
  "caption": "Tasks closed per week — resolved live on every render.",
  "query": {
   "filter": {
    "parent_id": "<epic-id>",
    "status": "done"
   },
   "over": {
    "bucket": "week",
    "on": "closed_at",
    "last": 10
   }
  }
 },
 {
  "type": "task-board",
  "query": {
   "parent_id": "<epic-id>",
   "limit": 200
  }
 }
]

[
 {
  "type": "steps",
  "steps": [
   {
    "title": "<Step title>",
    "blocks": [
